#include "../ring3_common.hpp"
// Morrow: cold-start continuity instrument. Measures the human reconstruction cost of current work.
static constexpr u32 W=800,H=550; static u32*pix; static u64 events,win; static bool dirty=true;
static int field=0,klass=0,scroll=0; static char work[104]={0},key[104]={0},where[92]={0},mins[8]={0}; static u32 wl=0,kl=0,hl=0,ml=0; static char logbuf[2400]={0}; static u32 exposed=0,entries=0;
static const char* classes[]={"RAM ONLY","THIS MACHINE","REPRODUCIBLE","EXTERNAL COPY"};
static u32 slen(const char*s){u32 n=0;while(s&&s[n])n++;return n;} static void cat(char*d,u32 cap,const char*s){u32 n=slen(d),i=0;while(s&&s[i]&&n+1<cap)d[n++]=s[i++];d[n]=0;}
static void num(char*out,u32 v){char t[12];u32 n=0;if(!v){out[0]='0';out[1]=0;return;}while(v&&n<11){t[n++]=(char)('0'+v%10);v/=10;}u32 z=0;while(n)out[z++]=t[--n];out[z]=0;}
static u32 parsemin(){u32 v=0;for(u32 i=0;i<ml;i++)if(mins[i]>='0'&&mins[i]<='9')v=v*10+(u32)(mins[i]-'0');return v;}
static void rr(i32 x,i32 y,i32 w,i32 h,i32 r,u32 c){rect(pix,W,H,x+r,y,w-2*r,h,c);rect(pix,W,H,x,y+r,w,h-2*r,c);for(i32 yy=0;yy<r;yy++)for(i32 xx=0;xx<r;xx++){i32 dx=r-xx-1,dy=r-yy-1;if(dx*dx+dy*dy<=r*r){rect(pix,W,H,x+xx,y+yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+yy,1,1,c);rect(pix,W,H,x+xx,y+h-1-yy,1,1,c);rect(pix,W,H,x+w-1-xx,y+h-1-yy,1,1,c);}}}
static void summarize(){exposed=entries=0;const char*m="REBUILD | ";const char*c="CLASS   | ";for(u32 i=0;logbuf[i];i++){u32 j=0;while(m[j]&&logbuf[i+j]==m[j])j++;if(!m[j]){i+=j;u32 v=0;while(logbuf[i]>='0'&&logbuf[i]<='9'){v=v*10+(u32)(logbuf[i]-'0');i++;}exposed+=v;entries++;}j=0;while(c[j]&&logbuf[i+j]==c[j])j++;if(!c[j]){i+=j;if(logbuf[i]=='E') { /* externally copied work is already survivable */ }}}}
static void load(){for(u32 i=0;i<sizeof(logbuf);i++)logbuf[i]=0;i64 h=sc(32,(u64)"/Home/Documents/MORROW.LOG",1);if(h>0){i64 n=sc(33,(u64)h,(u64)logbuf,sizeof(logbuf)-1);if(n>0&&n<(i64)sizeof(logbuf))logbuf[n]=0;sc(35,(u64)h);}summarize();dirty=true;}
static void save(){if(!wl)return;char line[620]={0};cat(line,sizeof(line),"WORK    | ");cat(line,sizeof(line),work);cat(line,sizeof(line),"\nCLASS   | ");cat(line,sizeof(line),classes[klass]);cat(line,sizeof(line),"\nWHERE   | ");cat(line,sizeof(line),where);cat(line,sizeof(line),"\nREBUILD | ");cat(line,sizeof(line),ml?mins:"0");cat(line,sizeof(line),"\nKEY     | ");cat(line,sizeof(line),key);cat(line,sizeof(line),"\n---\n");i64 h=sc(32,(u64)"/Home/Documents/MORROW.LOG",2|4);if(h>0){sc(34,(u64)h,(u64)line,slen(line));sc(35,(u64)h);}work[0]=key[0]=where[0]=mins[0]=0;wl=kl=hl=ml=0;field=0;load();}
static void box(int y,const char*label,const char*v,int idx,int width=444){text(pix,W,H,28,y,label,0x0096a3ad,1);rr(28,y+17,width,40,6,field==idx?0x00323e49:0x001d252c);text(pix,W,H,41,y+31,v,0x00eef2f4,1);if(field==idx)rect(pix,W,H,41+(i32)slen(v)*6,y+29,2,12,0x006ba5d7);}
static void draw(){fill(pix,W*H,0x00101418);rect(pix,W,H,0,0,W,60,0x0021262c);text(pix,W,H,22,17,"MORROW",0x00f3f5f6,2);text(pix,W,H,130,22,"WHAT SURVIVES IF THIS MACHINE DOES NOT?",0x009ba7af,1);
box(78,"CURRENT WORK STATE",work,0);text(pix,W,H,28,144,"SURVIVAL CLASS",0x0096a3ad,1);rr(28,161,220,38,6,0x002c3942);text(pix,W,H,42,175,classes[klass],klass<2?0x00e6ad68:0x007bc39a,1);text(pix,W,H,263,175,"CLICK TO CHANGE",0x007b8992,1);
box(214,"WHERE DOES THE ONLY USEFUL COPY LIVE?",where,1);box(286,"MINUTES TO RECONSTRUCT FROM NOTHING",mins,2,210);box(358,"SMALLEST CLUE YOUR FUTURE SELF NEEDS",key,3);rr(28,440,214,42,7,0x003b6f58);text(pix,W,H,73,455,"SEAL CHECKPOINT",0x00ffffff,1);
rr(500,78,272,422,9,0x00192228);text(pix,W,H,518,96,"COLD-START EXPOSURE",0x00e9eef1,1);char n[16];num(n,exposed);text(pix,W,H,518,123,n,0x00e6ad68,2);text(pix,W,H,568,128,"MINUTES TO REBUILD",0x008c99a1,1);num(n,entries);text(pix,W,H,518,158,n,0x00e9eef1,1);text(pix,W,H,542,158,"CHECKPOINTS",0x008c99a1,1);text(pix,W,H,518,190,"RECOVERY EVIDENCE",0x00e9eef1,1);int y=214;char line[40];u32 li=0,skip=0;for(u32 i=0;logbuf[i]&&y<480;i++){char c=logbuf[i];if(c=='\n'){line[li]=0;if(skip++>=(u32)scroll){text(pix,W,H,518,y,line,0x00bac5cb,1);y+=15;}li=0;}else if(li<38)line[li++]=c;}sc(SYS_PRESENT,win,(u64)pix,(u64)W*H*4);dirty=false;}
static void keyin(char c){char*b=field==0?work:field==1?where:field==2?mins:key;u32*n=field==0?&wl:field==1?&hl:field==2?&ml:&kl;u32 cap=field==0?102:field==1?90:field==2?6:102;if(c=='\b'){if(*n)b[--(*n)]=0;}else if(c=='\n'){field=(field+1)%4;}else if(c>=32&&c<127&&*n<cap&&(field!=2||(c>='0'&&c<='9'))){b[(*n)++]=c;b[*n]=0;}dirty=true;}
extern "C" __attribute__((section(".text.entry"))) void _davis_start(){pix=(u32*)(u64)sc(SYS_ALLOC,(u64)W*H*4);if(!pix)sc(0,1);win=makeWindow(events,W,H,96,58);if(!win)sc(0,2);load();for(;;){Wire m{};while(sc(SYS_IPC_RECV,events,(u64)&m)>0){if(m.type==KEY&&m.bytes==sizeof(KeyEv)){auto*k=(KeyEv*)m.payload;keyin((char)k->codepoint);}else if(m.type==POINTER&&m.bytes==sizeof(PtrEv)){auto*p=(PtrEv*)m.payload;if(p->flags&1){if(p->x>=28&&p->x<475){if(p->y>=95&&p->y<137)field=0;else if(p->y>=161&&p->y<199){klass=(klass+1)%4;dirty=true;}else if(p->y>=231&&p->y<273)field=1;else if(p->y>=303&&p->y<345)field=2;else if(p->y>=375&&p->y<417)field=3;else if(p->y>=440&&p->y<482)save();dirty=true;}}}else if(m.type==CLOSE)sc(0,0);}if(dirty)draw();sc(SYS_YIELD);}}
